using System.Diagnostics;
using System.Net;
using System.Net.Sockets;
using System.Text.Json;
using LaunchDesk.Core;

ProcessStartInfo Self(string mode){var start=new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,CreateNoWindow=true};if(Path.GetFileNameWithoutExtension(start.FileName).Equals("dotnet",StringComparison.OrdinalIgnoreCase))start.ArgumentList.Add(typeof(Workspace).Assembly.Location.Replace("LaunchDesk.Core.dll","LaunchDesk.Tests.dll"));start.ArgumentList.Add(mode);return start;}
if(args.FirstOrDefault()=="--launch-child"){await Task.Delay(4000);return 0;}
if(args.FirstOrDefault()=="--launch-parent"){using var child=Process.Start(Self("--launch-child"));await Task.Delay(700);return 0;}
if(args.FirstOrDefault()=="--capture-launch"){await File.WriteAllTextAsync(args[1],JsonSerializer.Serialize(new{Arguments=args.Skip(2).ToArray(),License=Environment.GetEnvironmentVariable("AVEVA_LICENSE_SERVER_LIST")}));return 0;}
var root=Path.Combine(Path.GetTempPath(),"LaunchDesk-tests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
int passed=0;var failures=new List<string>();
void Check(bool ok,string name){if(!ok)throw new Exception(name);}
async Task Test(string name,Func<Task> action){try{await action();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failures.Add(name+": "+e.Message);Console.WriteLine("FAIL "+name+": "+e.Message);}}
void MustThrow(Action action){try{action();}catch(Exception e)when(e is InvalidDataException or FileNotFoundException or DirectoryNotFoundException){return;}throw new Exception("Expected validation error");}
var appDir=Path.Combine(root,"Everything3D3.1");Directory.CreateDirectory(appDir);var exe=Path.Combine(appDir,"mon.exe");await File.WriteAllTextAsync(exe,"test fixture; not executable");var init=Path.Combine(appDir,"launch.init");await File.WriteAllTextAsync(init,"rem test");
Workspace Fixture(){var a=new AppEntry{Name="E3D 3.1",Version="3.1",ExecutablePath=exe,InitializationPath=init,WorkingDirectory=appDir};var l=new LicenseEntry{Name="Test",Host="127.0.0.1"};return new Workspace{Applications=[a],Licenses=[l],Profiles=[new LoginProfile{Name="MAR Design",AppId=a.Id,LicenseId=l.Id,CredentialKey="local-reference-only",AskForPassword=false}]};}
await Test("Atomic save, load and previous backup",async()=>{var w=Fixture();var store=new WorkspaceStore(Path.Combine(root,"workspace.json"));await store.SaveAsync(w);w.Profiles[0].Name="changed";await store.SaveAsync(w);Check((await store.LoadAsync())!.Profiles[0].Name=="changed","roundtrip");Check((await WorkspaceStore.ReadFileAsync(store.Path+".backup")).Profiles[0].Name=="MAR Design","backup");});
await Test("Corrupt config is preserved",async()=>{var path=Path.Combine(root,"bad.json");await File.WriteAllTextAsync(path,"{broken");try{await new WorkspaceStore(path).LoadAsync();throw new Exception("Expected JSON rejection");}catch(JsonException){}Check(await File.ReadAllTextAsync(path)=="{broken","original changed");});
await Test("Export strips credential references and forces local prompt",async()=>{var w=Fixture();var path=Path.Combine(root,"export.json");await WorkspaceStore.ExportAsync(w,[w.Profiles[0].Id],path);var json=await File.ReadAllTextAsync(path);Check(!json.Contains("local-reference-only"),"credential leaked");var exported=await WorkspaceStore.ReadFileAsync(path);Check(exported.Profiles[0].AskForPassword&&exported.Profiles[0].CredentialKey=="","prompt missing");});
await Test("Export only includes selected dependencies",async()=>{var w=Fixture();var other=new AppEntry{Name="Other"};w.Applications.Add(other);var otherLicense=new LicenseEntry{Name="Other"};w.Licenses.Add(otherLicense);w.Profiles.Add(new LoginProfile{Name="Other",AppId=other.Id,LicenseId=otherLicense.Id});var path=Path.Combine(root,"selection.json");await WorkspaceStore.ExportAsync(w,[w.Profiles[0].Id],path);var data=await WorkspaceStore.ReadFileAsync(path);Check(data.Profiles.Count==1&&data.Applications.Count==1&&data.Licenses.Count==1,"unselected dependencies leaked");});
await Test("Import remaps exact version and strips incoming credentials",async()=>{var w=Fixture();w.Applications[0].ExecutablePath=Path.Combine(root,"missing.exe");var path=Path.Combine(root,"import.json");await File.WriteAllTextAsync(path,JsonSerializer.Serialize(w,WorkspaceStore.Json));var local=Fixture().Applications;var p=await WorkspaceStore.PreviewAsync(path,local);Check(p.Data.Applications[0].ExecutablePath==exe,"version mapping");Check(p.Data.Profiles[0].CredentialKey=="","imported credential");Check(w.Applications[0].ExecutablePath!=exe,"input mutated");});
await Test("Ambiguous automatic mapping remains unresolved",async()=>{var w=Fixture();w.Applications[0].ExecutablePath="Z:\\missing.exe";var path=Path.Combine(root,"ambiguous.json");await File.WriteAllTextAsync(path,JsonSerializer.Serialize(w,WorkspaceStore.Json));var locals=Fixture().Applications;locals.Add(WorkspaceStore.Clone(locals[0]));var preview=await WorkspaceStore.PreviewAsync(path,locals);Check(preview.Data.Applications[0].ExecutablePath=="Z:\\missing.exe","silently chose ambiguous candidate");});
await Test("Merge remaps IDs, preserves source and handles duplicate names",()=>{var a=Fixture();var b=WorkspaceStore.Clone(a);var result=WorkspaceStore.Merge(a,b);Check(result.Profiles.Count==2&&result.Licenses.Count==2,"missing imports");Check(result.Applications.Count==1,"duplicate app");Check(result.Profiles[1].Name=="MAR Design (2)","collision");Check(result.Profiles[1].Id!=a.Profiles[0].Id,"id collision");Check(a.Profiles.Count==1,"mutated source");WorkspaceStore.Validate(result);return Task.CompletedTask;});
await Test("Dangling profile references rejected",()=>{var w=Fixture();w.Profiles[0].AppId="missing";MustThrow(()=>WorkspaceStore.Validate(w));return Task.CompletedTask;});
await Test("Duplicate IDs and future schemas rejected",()=>{var w=Fixture();w.Profiles.Add(WorkspaceStore.Clone(w.Profiles[0]));MustThrow(()=>WorkspaceStore.Validate(w));w=Fixture();w.SchemaVersion=2;MustThrow(()=>WorkspaceStore.Validate(w));return Task.CompletedTask;});
await Test("Server host and numeric ranges validated",()=>{foreach(var host in new[]{"4545@host","host;other","host name","host\nother"})MustThrow(()=>WorkspaceStore.ValidateLicense(new LicenseEntry{Host=host}));MustThrow(()=>WorkspaceStore.ValidateLicense(new LicenseEntry{RmsPort=0}));MustThrow(()=>WorkspaceStore.ValidateLicense(new LicenseEntry{PollSeconds=1}));MustThrow(()=>WorkspaceStore.ValidateLicense(new LicenseEntry{RmsCheck=RmsCheckKind.LocalService,Host="remote"}));return Task.CompletedTask;});
await Test("Native launch arguments and environment isolation",()=>{var w=Fixture();var before=Environment.GetEnvironmentVariable("AVEVA_LICENSE_SERVER_LIST");var p=LaunchService.Build(w.Profiles[0],w.Applications[0],w.Licenses[0],"test-password");Check(p.ArgumentList.Count==8&&p.ArgumentList[3]==init,"init quoting");Check(p.ArgumentList[5]=="SYSTEM/test-password","login token");Check(p.Environment["AVEVA_LICENSE_SERVER_LIST"]=="4545@127.0.0.1","endpoint");Check(Environment.GetEnvironmentVariable("AVEVA_LICENSE_SERVER_LIST")==before,"global environment modified");Check(!LaunchService.Preview(w.Profiles[0],w.Applications[0],w.Licenses[0]).Contains("test-password"),"preview leak");return Task.CompletedTask;});
await Test("Missing initialization and invalid login rejected",()=>{var w=Fixture();w.Applications[0].InitializationPath="missing.init";MustThrow(()=>LaunchService.Build(w.Profiles[0],w.Applications[0],w.Licenses[0],""));w=Fixture();w.Profiles[0].Project="bad project";MustThrow(()=>LaunchService.Build(w.Profiles[0],w.Applications[0],w.Licenses[0],""));w=Fixture();MustThrow(()=>LaunchService.Build(w.Profiles[0],w.Applications[0],w.Licenses[0],"bad\npassword"));return Task.CompletedTask;});
await Test("Local RMS service does not require RULES or TCP",async()=>{var e=new LicenseEntry{RmsCheck=RmsCheckKind.LocalService,RequireRules=false};var result=await LicenseMonitor.CheckAsync(e,_=>true);Check(result.Ready&&result.RulesMessage.Contains("不要求"),"old service false negative");var stopped=await LicenseMonitor.CheckAsync(e,_=>false);Check(!stopped.Ready,"stopped service false positive");});
await Test("TCP endpoint checks require both configured ports",async()=>{var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();try{var port=((IPEndPoint)listener.LocalEndpoint).Port;var e=new LicenseEntry{Host="127.0.0.1",RmsPort=port,RulesPort=port};Check((await LicenseMonitor.CheckAsync(e,_=>false)).Ready,"open ports unreachable");listener.Stop();Check(!(await LicenseMonitor.CheckAsync(e,_=>false)).Ready,"closed ports ready");}finally{listener.Stop();}});
await Test("Automatic discovery recognizes native and Marine entries",async()=>{var marine=Path.Combine(root,"Marine","OH12.1.SP4");Directory.CreateDirectory(marine);await File.WriteAllTextAsync(Path.Combine(marine,"marine.bat"),"@echo off");var found=await AppDiscovery.FindAsync([root]);Check(found.Any(a=>a.Kind==EntryKind.Monitor)&&found.Any(a=>a.Kind==EntryKind.MarineBatch),"discovery incomplete");});
await Test("Original desktop Marine adapter preserves vendor module comparison and nested handoff",async()=>{
 if(!OperatingSystem.IsWindows())return;
 var path=Path.Combine(root,"fake marine.bat");var capture=Path.Combine(root,"marine-receiver.json");
 await File.WriteAllTextAsync(path,"@echo off\r\nsetlocal\r\nset moduleArg=%1\r\n"+
  "if /i not \"%moduleArg%\"==\"Paragon\" exit /b 41\r\nif not \"%2\"==\"noconsole\" exit /b 42\r\n"+
  "if not \"%6\"==\"\" exit /b 43\r\nset args=%1 %2 %3 %4 %5\r\n"+
  "cmd /d /v:off /s /c \"\"%FIXTURE_HOST%\" --capture-launch \"%FIXTURE_OUTPUT%\" %args%\"\r\n");
 var w=Fixture();var a=w.Applications[0];var p=w.Profiles[0];a.Kind=EntryKind.MarineBatch;a.ExecutablePath=path;a.ProductCode="";
 p.Module="Paragon";p.Project="SEA";p.Mdb="///ALL";var before=Environment.GetEnvironmentVariable("AVEVA_LICENSE_SERVER_LIST");
 var start=LaunchService.Build(p,a,w.Licenses[0],"FixtureOnly");
 start.Environment["FIXTURE_HOST"]=Environment.ProcessPath!;start.Environment["FIXTURE_OUTPUT"]=capture;
 using var process=Process.Start(start)!;await process.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(10));
 Check(process.ExitCode==0,"vendor module parsing failed");using var actual=JsonDocument.Parse(await File.ReadAllTextAsync(capture));
 Check(actual.RootElement.GetProperty("Arguments").EnumerateArray().Select(x=>x.GetString()).SequenceEqual(new[]{"Paragon","noconsole","SEA","SYSTEM/FixtureOnly","/ALL"}),"nested handoff changed tokens");
 Check(actual.RootElement.GetProperty("License").GetString()=="4545@127.0.0.1"&&Environment.GetEnvironmentVariable("AVEVA_LICENSE_SERVER_LIST")==before,"license isolation lost");
 var preview=LaunchService.Preview(p,a,w.Licenses[0]);Check(preview.EndsWith("Paragon noconsole SEA SYSTEM/{本机凭据} /ALL")&&!preview.Contains("FixtureOnly"),"Marine preview mismatch");
});
await Test("Original desktop Monitor adapter preserves explicit Catalogue configuration and module case",()=>{
 var w=Fixture();var a=w.Applications[0];var p=w.Profiles[0];a.ProductCode="CATALOGUE";p.Project="SEA";p.Mdb="ALL";p.Module="Paragon";
 var start=LaunchService.Build(p,a,w.Licenses[0],"FixtureOnly");
 Check(start.ArgumentList.SequenceEqual(new[]{"PROD","CATALOGUE","init",init,"SEA","SYSTEM/FixtureOnly","/ALL","Paragon"}),"Monitor arguments differ from configured native command");
 return Task.CompletedTask;
});
await Test("Original desktop Marine adapter rejects unsupported multi-cmd input before execution",async()=>{
 var path=Path.Combine(root,"unsafe.cmd");await File.WriteAllTextAsync(path,"@echo off");
 var w=Fixture();var a=w.Applications[0];a.Kind=EntryKind.MarineBatch;a.ExecutablePath=path;
 foreach(var secret in new[]{"bad&value","bad%PATH%","bad!value","bad value","bad^value","bad|value","bad\"value","bad=value"})
  MustThrow(()=>LaunchService.Build(w.Profiles[0],a,w.Licenses[0],secret));
 var preview=LaunchService.Preview(w.Profiles[0],a,w.Licenses[0]);Check(!preview.Contains("bad"),"rejected secret reached preview");
});
await Test("Unsupported batch password quoting rejected",async()=>{var path=Path.Combine(root,"quoted.cmd");await File.WriteAllTextAsync(path,"@echo off");var w=Fixture();w.Applications[0].Kind=EntryKind.MarineBatch;w.Applications[0].ExecutablePath=path;MustThrow(()=>LaunchService.Build(w.Profiles[0],w.Applications[0],w.Licenses[0],"bad\"password"));});
await Test("Workspace defaults preserve the existing AppData location",()=>{var app=Path.Combine(root,"default-location");var local=Path.Combine(root,"local-data");Directory.CreateDirectory(app);Check(WorkspaceLocations.Resolve(app,local)==Path.Combine(local,"LaunchDesk","Workspaces","Fusion","workspace.json"),"legacy location changed");Check(!Directory.Exists(local),"path resolution wrote data");return Task.CompletedTask;});
await Test("Portable relative data paths resolve beside the executable",async()=>{var app=Path.Combine(root,"portable-app");Directory.CreateDirectory(app);await File.WriteAllTextAsync(Path.Combine(app,"portable.json"),"{\"DataDirectory\":\"Data\"}");var expected=Path.Combine(app,"Data","workspace.json");Check(WorkspaceLocations.Resolve(app,root)==expected,"portable path depends on working directory");Check(!Directory.Exists(Path.Combine(app,"Data")),"resolution unexpectedly created a folder");});
await Test("Portable absolute data paths preserve the chosen location",async()=>{var app=Path.Combine(root,"absolute-app");Directory.CreateDirectory(app);var target=Path.Combine(root,"shared-data");await File.WriteAllTextAsync(Path.Combine(app,"portable.json"),JsonSerializer.Serialize(new{DataDirectory=target}));Check(WorkspaceLocations.Resolve(app,root)==Path.Combine(target,"workspace.json"),"absolute path changed");});
await Test("Invalid portable settings fail without falling back to empty data",async()=>{var app=Path.Combine(root,"invalid-portable");Directory.CreateDirectory(app);await File.WriteAllTextAsync(Path.Combine(app,"portable.json"),"{}");MustThrow(()=>WorkspaceLocations.Resolve(app,root));Check(!File.Exists(Path.Combine(app,"Data","workspace.json")),"invalid settings invented a workspace");});
await Test("Archive refresh finds ZIP and 7z, sorts latest and sees added files",async()=>{var source=Path.Combine(root,"archives");Directory.CreateDirectory(source);var old=Path.Combine(source,"tool-old.7z");var latest=Path.Combine(source,"tool.ZIP");await File.WriteAllTextAsync(old,"old");await File.WriteAllTextAsync(latest,"latest");await File.WriteAllTextAsync(Path.Combine(source,"unfinished.zip.crdownload"),"partial");File.SetLastWriteTimeUtc(old,DateTime.UtcNow.AddHours(-1));var first=ArchiveCatalog.Scan(source);Check(first.Count==2&&first[0].FullPath==latest,"archive list or order incorrect");var added=Path.Combine(source,"new-download.7z");await File.WriteAllTextAsync(added,"new");File.SetLastWriteTimeUtc(added,DateTime.UtcNow.AddMinutes(1));Check(ArchiveCatalog.Scan(source)[0].FullPath==added,"refresh missed new package");Check(await File.ReadAllTextAsync(old)=="old","scan modified source");});
await Test("Archive scan handles an absent source folder",()=>{Check(ArchiveCatalog.Scan(Path.Combine(root,"missing-archives")).Count==0,"missing folder invented packages");return Task.CompletedTask;});
ProbeResult Probe(bool good)=>new("test",good,good,"rms","rules",1,DateTimeOffset.UtcNow);
await Test("License retry recovers a transient failure without exhausting attempts",async()=>{int calls=0;var result=await LicenseMonitor.RetryAsync(_=>Task.FromResult(Probe(++calls==2)),3,TimeSpan.Zero);Check(result.Ready&&result.Attempts==2&&calls==2,"retry did not recover");});
await Test("Persistent license failure remains a failure after bounded retries",async()=>{int calls=0;var result=await LicenseMonitor.RetryAsync(_=>{calls++;return Task.FromResult(Probe(false));},3,TimeSpan.Zero);Check(!result.Ready&&result.Attempts==3&&calls==3,"failure was hidden or unbounded");});
await Test("Cancelled license checks stop before probing",async()=>{using var cancellation=new CancellationTokenSource();cancellation.Cancel();int calls=0;try{await LicenseMonitor.RetryAsync(_=>{calls++;return Task.FromResult(Probe(true));},3,TimeSpan.Zero,cancellation.Token);throw new Exception("cancellation ignored");}catch(OperationCanceledException){}Check(calls==0,"cancelled probe ran");});
await Test("Disconnect alert requires three failed rounds and fires once",()=>{var health=new ConnectionHealth();health.Observe(Probe(true));var first=health.Observe(Probe(false));var second=health.Observe(Probe(false));var third=health.Observe(Probe(false));var fourth=health.Observe(Probe(false));Check(first.Result.Rechecking&&second.Result.Rechecking&&!first.NotifyDisconnect&&!second.NotifyDisconnect,"transient outage alerted");Check(!third.Result.Rechecking&&third.NotifyDisconnect&&!fourth.NotifyDisconnect,"confirmed outage did not alert once");health.Observe(Probe(true));Check(health.Observe(Probe(false)).Result.ConsecutiveFailures==1,"recovery did not reset failures");return Task.CompletedTask;});
await Test("Launch state distinguishes handoff, window ready and process exit",()=>{var started=DateTimeOffset.UtcNow;var state=LaunchProgress.Submitted(123);state=LaunchProgress.Observe(state,new(1,0,true,0,started.AddSeconds(2)),started);Check(state.Phase==LaunchPhase.Starting,"launcher handoff was reported as failure");state=LaunchProgress.Observe(state,new(1,1,true,0,started.AddSeconds(3)),started);Check(state.Phase==LaunchPhase.Running&&state.Detail.Contains("许可签出"),"ready window missing or overclaimed login");state=LaunchProgress.Observe(state,new(0,0,true,0,started.AddSeconds(4)),started);Check(state.Phase==LaunchPhase.Exited,"process exit not reflected");return Task.CompletedTask;});
await Test("Unconfirmed launch is not reported as success; nonzero exit fails",()=>{var started=DateTimeOffset.UtcNow;var state=LaunchProgress.Submitted(123);Check(LaunchProgress.Observe(state,new(0,0,true,0,started.AddSeconds(95)),started).Phase==LaunchPhase.Unconfirmed,"detached launch falsely succeeded");Check(LaunchProgress.Observe(state,new(0,0,true,17,started.AddSeconds(2)),started).Phase==LaunchPhase.Failed,"nonzero exit not failed");return Task.CompletedTask;});
await Test("Process tracker follows a child after its launcher exits",async()=>{if(!OperatingSystem.IsWindows())return;var process=Process.Start(Self("--launch-parent"))!;using var tracker=new LaunchProcessTracker(process);LaunchObservation observation=tracker.Observe();for(var i=0;i<15&&!observation.RootExited;i++){await Task.Delay(100);observation=tracker.Observe();}Check(observation.RootExited&&observation.ExitCode==0&&observation.AliveProcesses>0,"child handoff lost");await Task.Delay(4200);Check(tracker.Observe().AliveProcesses==0,"finished child still alive");});
Console.WriteLine($"RESULT {passed} passed, {failures.Count} failed");
if(args.Length>0)await File.WriteAllTextAsync(args[0],JsonSerializer.Serialize(new{Passed=passed,Failed=failures.Count,Failures=failures},WorkspaceStore.Json));
try{Directory.Delete(root,true);}catch(IOException){}
return failures.Count==0?0:1;
